import time
from functools import wraps

def timed(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        print(f"{func.__name__} executed in {time.perf_counter() - start:.4f}s")
        return result
    return wrapper

@timed
def compute():
    return sum(i * i for i in range(100000))

